  "anomalies": [
    {
      "category": "other",
      "components": ["T1", "T2", "T7", "T8", "R34", "R21"],
      "pins": ["T1.1", "T2.1", "T7.3", "T8.3"],
      "nets": ["+3V3", "NET0031", "NET0046", "GND"],
      "observed": "Both low-side N-MOSFET gates are pulled up to +3V3 by 10 kΩ resistors (R34 for T1 and R21 for T2). Their NPN predrivers (T7 and T8) pull the gates low when driven on. With the MCU pins uninitialized or high-impedance, the NPNs are off, so the pull-ups turn the MOSFETs on.",
      "expected": "The pump and ATO valve switches should default to off while the MCU is resetting or unpowered. Their gate bias should hold the N-MOSFETs off unless the controller actively commands them on.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "Main Pump: R34 10k from +3V3 to the T1 gate; T7 is a BT3904 gate predriver. Valve: R21 10k from +3V3 to the T2 gate; T8 is a BT3904 gate predriver. Sheet 1, page 1."
        },
        {
          "source": "spec",
          "quote": "T2 — IRLR2905 ... Main circulation-pump low-side switch; T3 — AON6407 ... ATO solenoid-valve low-side switch. §2, page 1."
        }
      ],
      "impact": "The main pump and ATO valve can be energized during MCU startup, reset, or loss of GPIO drive. In particular, an ATO valve that opens when energized could fill the reservoir without the controller running.",
      "confidence": 0.84
    }
  ],
  "summary": "The pump and valve MOSFET gates are biased on by pull-ups, while the NPN stages only pull them off. This makes both actuators active when the MCU pins are high-impedance, rather than safely off by default."
}

